import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                           torch::Tensor positive,
                                           torch::Tensor negative,
                                           double margin,
                                           double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

constexpr int NUM_BINS = 128;
template <typename T>
__global__ void triplet_margin_loss_kernel(
    const T* __restrict__ A,
    const T* __restrict__ P,
    const T* __restrict__ N,
    float* __restrict__ out_sum,
    int B, int D, float margin, float eps)
{
  int row = blockIdx.x;
  if (row >= B) return;
  const T* a_ptr = A + (int64_t)row * D;
  const T* p_ptr = P + (int64_t)row * D;
  const T* n_ptr = N + (int64_t)row * D;
  int tid = threadIdx.x;
  int nthreads = blockDim.x;
  float sum_ap = 0.f;
  float sum_an = 0.f;
  int D4 = D >> 2;
  const float4* a4 = reinterpret_cast<const float4*>(a_ptr);
  const float4* p4 = reinterpret_cast<const float4*>(p_ptr);
  const float4* n4 = reinterpret_cast<const float4*>(n_ptr);
  for (int i = tid; i < D4; i += nthreads) {
    float4 av4 = a4[i];
    float4 pv4 = p4[i];
    float4 nv4 = n4[i];
    float dap0 = av4.x - pv4.x + eps;
    float dap1 = av4.y - pv4.y + eps;
    float dap2 = av4.z - pv4.z + eps;
    float dap3 = av4.w - pv4.w + eps;
    float dan0 = av4.x - nv4.x + eps;
    float dan1 = av4.y - nv4.y + eps;
    float dan2 = av4.z - nv4.z + eps;
    float dan3 = av4.w - nv4.w + eps;
    sum_ap += dap0 * dap0 + dap1 * dap1 + dap2 * dap2 + dap3 * dap3;
    sum_an += dan0 * dan0 + dan1 * dan1 + dan2 * dan2 + dan3 * dan3;
  }
  // handle any remaining tail elements when D is not divisible by 4
  for (int i = D4 * 4 + tid; i < D; i += nthreads) {
    float av = a_ptr[i];
    float pv = p_ptr[i];
    float nv = n_ptr[i];
    float dap = av - pv + eps;
    float dan = av - nv + eps;
    sum_ap += dap * dap;
    sum_an += dan * dan;
  }
  // Warp-level reduction
  #pragma unroll
  for (int offset = 16; offset > 0; offset >>= 1) {
    sum_ap += __shfl_down_sync(0xffffffff, sum_ap, offset);
    sum_an += __shfl_down_sync(0xffffffff, sum_an, offset);
  }
  __shared__ float shared_ap[32];
  __shared__ float shared_an[32];
  int lane = tid & 31;
  int warp_id = tid >> 5;
  if (lane == 0) {
    shared_ap[warp_id] = sum_ap;
    shared_an[warp_id] = sum_an;
  }
  __syncthreads();
  int num_warps = (nthreads + 31) / 32;
  if (tid < 32) {
    float val_ap = (tid < num_warps) ? shared_ap[tid] : 0.f;
    float val_an = (tid < num_warps) ? shared_an[tid] : 0.f;
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
      val_ap += __shfl_down_sync(0xffffffff, val_ap, offset);
      val_an += __shfl_down_sync(0xffffffff, val_an, offset);
    }
    if (tid == 0) {
      float d_ap = sqrtf(val_ap);
      float d_an = sqrtf(val_an);
      float loss = margin + d_ap - d_an;
      loss = loss > 0.f ? loss : 0.f;
      // Fuse the reduction directly into this kernel via a single atomicAdd
      // per block, avoiding an extra kernel launch and the round-trip
      // through global memory for a separate reduction pass.
      atomicAdd(out_sum, loss);
    }
  }
}
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor,
                                           torch::Tensor positive,
                                           torch::Tensor negative,
                                           double margin,
                                           double eps) {
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "all inputs must be CUDA tensors");
  TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2,
              "inputs must be 2D [B, D]");
  TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(),
              "anchor, positive, negative must have same shape");
  TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
              positive.scalar_type() == at::kFloat &&
              negative.scalar_type() == at::kFloat,
              "only float32 supported");
  auto a_c = anchor.contiguous();
  auto p_c = positive.contiguous();
  auto n_c = negative.contiguous();
  int B = (int)a_c.size(0);
  int D = (int)a_c.size(1);
  auto sum_tensor = torch::zeros({}, a_c.options());
  int threads = 1024;
  dim3 block(threads);
  dim3 grid(B);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  triplet_margin_loss_kernel<float><<<grid, block, 0, stream>>>(
      a_c.data_ptr<float>(),
      p_c.data_ptr<float>(),
      n_c.data_ptr<float>(),
      sum_tensor.data_ptr<float>(),
      B, D, (float)margin, (float)eps
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "triplet_margin_loss_kernel launch failed: ", cudaGetErrorString(err));
  auto loss_mean = sum_tensor / static_cast<double>(B);
  return loss_mean;
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include",
                          "/root/cutegen_test/cutegen/cutlass/include/cute/"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Triplet Margin Loss implemented with a fused custom CUDA/CUTE kernel.
    Computes: mean( max(margin + ||a - p + eps||_2 - ||a - n + eps||_2, 0) )
    matching torch.nn.TripletMarginLoss default settings (p=2, eps=1e-6, reduction='mean').
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self.eps = 1e-6
        self._ext = triplet_ext

    def forward(self, anchor, positive, negative):
        return self._ext.triplet_margin_loss_forward(
            anchor, positive, negative, self.margin, self.eps
        )

